{"judgments": [
  {"clause_id": "c001", "issues": [
    {"issue": "The Initial Period ends eight months after delivery of the Master Recordings comprising the \"Recording Obligation\", a term the agreement never defines (paragraph 2.02 defines only \"Minimum Recording Obligation\"). The end date of the Term therefore turns on an undefined phrase.", "type": 1, "prob": 0.24},
