  {"clause_id": "c003", "issues": [
    {"issue": "The warranty that Artist will record \"exclusively for Grantor and PRI\" sits awkwardly with PRI's engagement of Grantor to furnish \"exclusive services\", leaving the scope of the exclusivity (and to whom it runs) open.", "type": 1, "prob": 0.18},
    {"issue": null, "type": 2, "prob": 0.08}
