  {"clause_id": "c005", "issues": [
    {"issue": "\"To the best of their ability\" and \"first-class standards for production in the Phonograph Record industry\" are undefined performance benchmarks with no measurable content. A court would have to supply the standard.", "type": 1, "prob": 0.26},
    {"issue": null, "type": 2, "prob": 0.07}
  ]},
  {"clause_id": "c006", "issues": [
    {"issue": "PRI may disapprove a Composition for defamation, libel or infringement \"or which is subject to Objection for any other legal reason whatsoever\", and may disapprove a studio if its use \"would otherwise in any way substantially hinder or prevent\" recording; these catch-alls sit against the enumerated specifics and their reach is uncertain.", "type": 1, "prob": 0.30},
    {"issue": null, "type": 2, "prob": 0.11}
  ]},
  {"clause_id": "c007", "issues": [
    {"issue": "Masters must be \"technically satisfactory\" and embody Recordings that are \"first-class (as that term is understood in the record industry)\"; whether a delivery qualifies is left to an undefined industry standard that both sides could read differently. This is the classic acceptance-standard ambiguity in recording agreements.", "type": 1, "prob": 0.31},
    {"issue": null, "type": 2, "prob": 0.09}
