  ]},
  {"clause_id": "c010", "issues": [
    {"issue": "\"Reasonably consistent in concept and style\" and \"similar in general artistic concept and style\" set a purely subjective artistic benchmark with no ascertainable boundary. A dispute over whether a delivered Album complied would turn entirely on that phrase.", "type": 1, "prob": 0.24},
    {"issue": null, "type": 2, "prob": 0.09}
