  {"clause_id": "c016", "issues": [
    {"issue": "\"Satisfactory completion\" of the Article 3 and 4 procedures is made the condition of delivery without saying whose satisfaction governs or by what standard. The final clause then deems accepted and released Masters to count, which cuts against the preceding non-waiver language.", "type": 1, "prob": 0.26},
    {"issue": null, "type": 2, "prob": 0.11}
