  {"clause_id": "c022", "issues": [
    {"issue": null, "type": 1, "prob": 0.11},
    {"issue": "The chapeau of 5.01(b) confines the sub-clauses to \"sales of Records in the United States during the Term\", yet paragraph 3.03 makes PRI's use of out-takes subject to 5.01(b)(i) generally, leaving the territorial and temporal reach of the out-take consent unclear.", "type": 2, "prob": 0.20}
